package io.xeros.solo;
import io.xeros.*;import io.xeros.model.*;import io.xeros.content.bosses.*;import io.xeros.content.combat.*;import io.xeros.content.combat.death.*;import io.xeros.content.skills.slayer.Task;import io.xeros.content.teleportation.inter.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.npc.actions.NPCHitPlayer;import io.xeros.model.entity.npc.drops.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.model.items.*;import io.xeros.model.definitions.*;import java.util.*;import java.lang.reflect.*;
public final class BossRoutesCheck {
 static void ok(boolean b,String s){BossesPlayableCheck.ok(b,s);}static Player actor(){Player p=BossesPlayableCheck.actor();p.setLoginName("bossroutes63qa");p.setDisplayName("Bossroutes63qa");p.respawnTimer=-6;at(p,3101,3509,0);return p;}
 static void at(Player p,int x,int y,int h){p.absX=x;p.absY=y;p.heightLevel=h;p.mapRegionX=(x>>3)-6;p.mapRegionY=(y>>3)-6;p.currentX=p.getLocalX();p.currentY=p.getLocalY();p.resetWalkingQueue();p.setTeleportToX(-1);p.setTeleportToY(-1);}
 static void routes(){Map<String,int[]> positions=new LinkedHashMap<>();positions.put("Corporeal Beast",new int[]{2964,4382,2});positions.put("Dagannoth Kings",new int[]{1913,4367,0});positions.put("Giant Mole",new int[]{2993,3376,0});positions.put("Kalphite Queen",new int[]{3510,9496,2});positions.put("Kraken",new int[]{2280,10016,0});positions.put("Cerberus",new int[]{1310,1248,0});positions.put("Vorkath",new int[]{2272,4050,0});positions.put("Zulrah",new int[]{2203,3056,0});positions.put("Sarachnis",new int[]{1842,9926,0});positions.put("Obor",new int[]{3097,9833,0});positions.put("Bryophyta",new int[]{3174,9898,0});
 List<TeleportButton> bosses=TeleportInterfaceConstants.TELEPORT_CONTAINER_LIST.get(1).getButtonList();ok(bosses.stream().filter(b->b.getName().equals("Nex")).count()==1,"Duplicate Nex route");for(Map.Entry<String,int[]> e:positions.entrySet()){Player p=actor();TeleportButton b=bosses.stream().filter(v->v.getName().equals(e.getKey())).findFirst().orElseThrow();b.getAction().accept(p);int[] a=e.getValue();ok(p.teleTimer>0&&p.teleX==a[0]&&p.teleY==a[1]&&p.teleHeight==a[2],"Route "+e.getKey()+" timer="+p.teleTimer+" pos="+p.teleX+","+p.teleY+","+p.teleHeight);BossesPlayableCheck.clear(p);}Player p=actor();bosses.stream().filter(b->b.getName().equals("Nex")).findFirst().orElseThrow().getAction().accept(p);ok(p.getInstance() instanceof io.xeros.content.bosses.nex.Nex,"Nex menu action");BossesPlayableCheck.clear(p);System.out.println("BOSSES_11_LOBBY_TELEPORT_ACTIONS_AND_UNIQUE_NEX_DIRECT_ENTRY_PASS");}
 @SuppressWarnings("unchecked")static void deaths()throws Exception{Field f=Server.getDropManager().getClass().getDeclaredField("groups");f.setAccessible(true);Map<List<Integer>,TableGroup> groups=(Map<List<Integer>,TableGroup>)f.get(Server.getDropManager());int[] ids={2215,2205,3129,3162,2265,2266,2267,239,319,5779,965,5862,499,8713,7416,8195,8028,2042};
 for(int id:ids){Player p=actor();at(p,3200,3200,0);p.getHealth().setMaximumHealth(5000);p.getHealth().reset();TableGroup group=groups.values().stream().filter(g->g.getNpcIds().contains(id)).findFirst().orElseThrow(()->new AssertionError("No native drop table "+id));ok(!group.isEmpty(),"Empty native drops "+id);for(Table t:group)for(Drop d:t)ok(ItemDef.forId(d.getItemId())!=null&&d.getMinimumAmount()>0&&d.getMaximumAmount()>=d.getMinimumAmount(),"Bad native item "+id);
 List<Table> original=new ArrayList<>(group);Table deterministic=new Table(TablePolicy.CONSTANT,1);deterministic.add(new Drop(List.of(id),995,7,7));group.clear();group.add(deterministic);NPC n=NPCSpawning.spawnNpc(p,id==8028?8026:id,3201,3200,0,0,20,false,false);if(id==8028)n.requestTransform(8028);try{n.oldIndex=1;n.setPlayerAttackingIndex(1);n.setAttackType(CombatType.MELEE);int hp=p.getHealth().getCurrentHealth();for(int i=0;i<30&&p.getHealth().getCurrentHealth()==hp;i++)NPCHitPlayer.applyDamage(n,Server.npcHandler);ok(p.getHealth().getCurrentHealth()<hp,"No boss damage "+id);int nhp=n.getHealth().getCurrentHealth();n.appendDamage(p,1,Hitmark.HIT);ok(n.getHealth().getCurrentHealth()==nhp-1,"Cannot hit boss "+id);int kc=p.getNpcDeathTracker().getKc(n.getName());n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);for(int i=0;i<40&&!n.needRespawn;i++)Server.npcHandler.getNpcProcess().process(n.getIndex());ok(n.needRespawn&&p.getNpcDeathTracker().getKc(n.getName())==kc+1,"Death/KC "+id);GroundItem drop=Server.itemHandler.getOwnedGroundItem(p,995,0);ok(drop!=null&&drop.getAmount()==7,"Drop delivery "+id);for(int i=0;i<3;i++)Server.npcHandler.getNpcProcess().process(n.getIndex());ok(p.getNpcDeathTracker().getKc(n.getName())==kc+1,"Duplicate death "+id);Server.itemHandler.removeGroundItem(p,drop,true);ok(p.getItems().getInventoryCount(995)==7,"Pickup "+id);ok(PlayerSave.saveGameInstant(p),"Save "+id);Player q=AttackDefencePlayableCheck.actor();q.setLoginName("bossroutes63qa");ok(PlayerSave.loadGame(q,"bossroutes63qa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.getItems().getInventoryCount(995)==7&&q.getNpcDeathTracker().getKc(n.getName())==kc+1,"Reload "+id);SkillsAuditCheck.clear(q);System.out.println("BOSS_SHARED_COMBAT_DEATH_DROP_PICKUP_KC_SAVE_RELOAD_"+id+"_PASS");}finally{group.clear();group.addAll(original);n.unregisterInstant();BossesPlayableCheck.clear(p);}}
 System.out.println("BOSSES_18_NATIVE_TABLES_SHARED_TWO_WAY_COMBAT_REAL_DEATH_ONE_KC_CONTROLLED_DROP_PICKUP_AND_REAL_SAVE_RELOAD_PASS");}
 static void kraken()throws Exception{Player p=actor();Kraken.init(p);ok(p.getInstance() instanceof KrakenInstance&&p.getInstance().getNpcs().stream().anyMatch(n->n.getNpcId()==494),"Solo owner without task cannot enter Kraken");ok(PlayerSave.saveGameInstant(p),"Kraken save");Player q=AttackDefencePlayableCheck.actor();q.setLoginName("bossroutes63qa");ok(PlayerSave.loadGame(q,"bossroutes63qa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.getTeleportToX()==Configuration.START_LOCATION_X&&q.getTeleportToY()==Configuration.START_LOCATION_Y&&q.heightLevel==0,"Kraken abandoned instance reload");SkillsAuditCheck.clear(q);Object arena=p.getInstance();Kraken.init(p);ok(p.getInstance()==arena,"Duplicate Kraken entry");BossesPlayableCheck.clear(p);p=actor();p.isDead=true;Kraken.init(p);ok(p.getInstance()==null,"Dead Kraken entry");BossesPlayableCheck.clear(p);for(int c=0;c<4;c++){p=actor();p.getRights().setPrimary(Right.PLAYER);if(c>0){p.getSlayer().setTask(Optional.of(new Task(new String[]{"kraken"},87,100,1,2,new String[]{"test"},new int[]{2280,10016,0})));p.getSlayer().setTaskAmount(c==1?0:2);}if(c==2)p.playerXP[18]=p.getPA().getXPForLevel(86)+1;Kraken.init(p);ok((p.getInstance()!=null)==(c==3),"Kraken task/level condition "+c);BossesPlayableCheck.clear(p);}System.out.println("BOSSES_KRAKEN_SOLO_OWNER_NO_TASK_ENTRY_SPAWN_SAFE_RELOG_DUPLICATE_DEAD_AND_REGULAR_TASK_LEVEL_GUARDS_PASS");}
 static void playerDeath(){Player p=actor();io.xeros.content.bosses.nex.Nex.enterSolo(p);BossesPlayableCheck.applied(p);io.xeros.content.instances.InstancedArea arena=p.getInstance();p.hasNexVirus=true;p.isDead=true;p.getHealth().setCurrentHealth(0);PlayerDeath.giveLife(p);ok(p.getInstance()==null&&arena.isDisposed()&&!p.hasNexVirus&&!p.isDead&&p.getTeleportToX()==Configuration.RESPAWN_X&&p.getTeleportToY()==Configuration.RESPAWN_Y&&p.getHealth().getCurrentHealth()>0,"Nex player death cleanup/respawn "+p.getInstance()+" disposed="+arena.isDisposed()+" virus="+p.hasNexVirus+" dead="+p.isDead+" pos="+p.getTeleportToX()+","+p.getTeleportToY()+" HP="+p.getHealth().getCurrentHealth());BossesPlayableCheck.clear(p);System.out.println("BOSSES_NEX_PLAYER_DEATH_DISPOSE_VIRUS_CLEAR_AND_RESPAWN_PASS");}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;routes();kraken();deaths();playerDeath();System.out.println("BOSSES_ROUTES_AND_SHARED_LIFECYCLE_V63_PASS");System.exit(0);}
}
